<?php
require getenv('GRW_WP_ROOT').'/wp-load.php';
use Webifya\GRW\{Locations,Reviews,Widgets,Installer};global $wpdb;$file=getenv('GRW_SNAPSHOT');$mode=getenv('GRW_UPGRADE_MODE');
if($mode==='seed'){$l=Locations::save(['name'=>'Upgrade preservation fixture','provider'=>'import','active'=>true,'business_name'=>'Sample upgrade business']);Reviews::import([['external_id'=>'upgrade-1','reviewer'=>'Sample upgrade reviewer বাংলা','rating'=>5,'content'=>'Synthetic upgrade fixture','review_date'=>'2024-01-01']],$l);Widgets::save(['name'=>'Styled upgrade widget','config'=>['locations'=>[$l],'card'=>'#abc123','gap'=>31,'heading'=>'CUSTOM UPGRADE HEADING']]);update_option('grw_settings',['analytics'=>true,'consent_required'=>true,'retention'=>180,'delete_data'=>false]);$wpdb->insert($wpdb->prefix.'grw_analytics',['day'=>'2026-10-08','widget_id'=>1,'location_id'=>0,'event'=>'impression','total'=>37]);}
